 for(unsigned record=0;record<3;++record){storm_ship_laser::Plane dose{{-1,0,0},0};for(unsigned n=0;n<4;++n){auto sample=b;sample.start={x,1,static_cast<float>(record*4+n)*.05f};sample.depth=.3f;dose.beams.push_back(sample);}auto started=std::chrono::steady_clock::now();auto previous=retained;auto next=storm_ship_laser::splitSurface(retained,dose,wood);assert(next.complete);auto separated=storm_ship_laser::detachEnclosed(previous,next.kept);assert(separated.empty());retained=std::move(next.kept);double cost=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-started).count();std::cout<<"actual record="<<record<<" cutters="<<retained.cutters.size()<<" walls="<<triangleCount(retained.finiteWalls)<<" triangles="<<triangleCount(storm_ship_laser::canonicalMesh(retained))<<" cpu_ms="<<cost<<std::endl;assert(ray(storm_ship_laser::canonicalMesh(retained),{100,1,10},{-100,1,10})==ray(original,{100,1,10},{-100,1,10}));}

